import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第91章 哑下去","description":"","frontmatter":{},"headers":[],"relativePath":"第91章_公共电话亭.md","filePath":"第91章_公共电话亭.md"}'),o={name:"第91章_公共电话亭.md"};function r(n,p,s,c,i,u){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第91章-哑下去" tabindex="-1">第91章 哑下去 <a class="header-anchor" href="#第91章-哑下去" aria-label="Permalink to &quot;第91章 哑下去&quot;">​</a></h1><p>那年夏天，新号先哑的。</p><p>这件事不是她决定的。</p><p>是她那边的生活变了。</p><p>四月她换了手机。</p><p>旧手机她卖掉了，卖之前她把里面的东西清了一遍。</p><p>新手机上她只装了她每天要用的那些。</p><p>那个号，是&quot;每天不用&quot;的那一个。</p><p>她说，我今天在新手机上没装那个。</p><p>我说，为什么。</p><p>她说，装不了，那个商店里下架了。</p><p>我说，你以前是从网页进的。</p><p>她说，我现在懒得弄。</p><p>她说，我这边忙到每天回到屋里十一点。</p><p>她说，我十一点以后只想躺在床上刷一个不用动脑的东西。</p><p>她说，那个号要登录，要输密码，密码我记不住。</p><p>我说，你把密码改了。</p><p>她说，改了三次。</p><p>她说，我每次改是因为我妈那边出一次事。</p><p>她说，我现在懒得再记第四个。</p><p>我说，那我们说什么。</p><p>她说，说那个号。</p><p>她说，就那个号。</p><p>我说，你妈看的那个。</p><p>她说，对。</p><p>我说，你那天讲过，那个号上你说的不是你的话。</p><p>她说，我今天重新想了一下。</p><p>她说，不是我的那句话，是讲给你听的。</p><p>她说，我这两年在上面发猫，发布，发橙子，发一块布。</p><p>她说，那些东西本来就是真的。</p><p>她说，它只是不是一个我。</p><p>她说，它是一个我能让我妈放心、让我姨高兴、让我室友不追问的我。</p><p>她说，我现在每天只能拿这一个。</p><p>我说，那另一个呢。</p><p>她说，等我有精神。</p><p>我说，你什么时候有精神。</p><p>她说，我不知道。</p><p>五月，那个号上她一次也没上。</p><p>六月，两次。</p><p>两次都是她那边夜里三点，发的是一模一样的四个字：</p><p>&quot;我还在。&quot;</p><p>我看到第一次那两个字的时候，我一点没回。</p><p>因为我懂那四个字。</p><p>她不是来讲话的。</p><p>她是来告诉我那个号没死。</p><p>第二次我看到&quot;我还在&quot;，我回的是：我知道。</p><p>她说，你别等我。</p><p>我说，我没等你。</p><p>她说，你在。</p><p>我说，我在等那个号，我没在等你。</p><p>她说，那你等什么。</p><p>我说，我等这个号上你什么时候能讲一句不带密码的话。</p><p>她没回。</p><p>那两个月，我们所有的东西都在旧号上。</p><p>旧号上讲话是一种什么感觉，我讲一件具体的。</p><p>六月有一天，她在旧号上发：我今天去医院了。</p><p>我说，怎么了。</p><p>她说，我那个牙，我一直没管，今天肿了。</p><p>我说，看了吗。</p><p>她说，看了，拍片，说要治，两千八。</p><p>我说，你治了吗。</p><p>她说，我做了第一步，剩下的我说我考虑。</p><p>我说，你考虑什么。</p><p>她说，我在算我剩下的那两千八要分几个月。</p><p>我说，你别分。</p><p>她说，我这边不分我就下个月交不起那个展的费用。</p><p>我说，你那个展不是公费吗。</p><p>她说，公费是框和运，我自己那三张图我要自己出。</p><p>我说，你先治牙。</p><p>她说，你别讲了。</p><p>我说，为什么。</p><p>她说，因为这条我妈能看见。</p><p>她说，她要是看见我牙疼两千八，她今天晚上睡不着。</p><p>她说，她睡不着她明天要给我妈打电话。</p><p>她说，我们两家那个电话一打，我妈要问我为什么不告诉她。</p><p>她说，我问我自己，我为什么说不了。</p><p>她说，因为我讲一句&quot;我牙疼&quot;，我要接着讲我这两年在做什么。</p><p>她说，我只能讲到这里。</p><p>我把手机放下，坐在那儿很久。</p><p>然后我拿起来，在那个号上，回了一句很没用的话。</p><p>我回的是：那你今天吃饭了吗。</p><p>她回：吃了。</p><p>我说：吃的什么。</p><p>她说：粥。</p><p>我说：牙疼喝粥，对的。</p><p>她说：你怎么不劝我。</p><p>我说：劝什么。</p><p>她说：劝我去治。</p><p>我说，你现在在这儿，你跟我讲这些的时候，你妈随时能拿起这个手机。</p><p>我说，我要是这时候劝你去治，你就要开始跟我解释为什么不治。</p><p>我说，你一解释，你就要在这个手机上打一段你不想让别人看见的话。</p><p>我说，我不劝。</p><p>她说，你今天怎么这么懂事。</p><p>我说，我在这台手机上不敢讲别的。</p><p>她说，我知道。</p><p>她说，所以我们两个现在是在一台公共的电话亭里讲话。</p><p>她说，声音要小。</p><p>我说，我知道。</p><p>她说，可是我不想下去。</p><p>她说，下去我就没有话跟你讲。</p><p>那年七月，我在旧号上跟她讲了两年里最长的一次话。</p><p>一共一百三十七条。</p><p>那一次里面有一件很小、但是我一直记得的事。</p><p>那天她发了一个图。</p><p>图里是她那张桌子。</p><p>桌上有一台新的电脑，一个很干净的杯子，一副新的耳机。</p><p>她说，我今天买了这个杯子。</p><p>我说，多少钱。</p><p>她说，你别问。</p><p>我说，我问问。</p><p>她说，十九。</p><p>她说，我今天拿它装了水，我拿着它在屋里走了一圈。</p><p>她说，我以前那个杯子是外卖送的纸杯，我用了一年半。</p><p>我说，为什么买这个。</p><p>她说，因为我今天在那个店里，我拿起来看底部。</p><p>她说，底部写了一个很普通的牌子。</p><p>她说，我那时候想，我用一个纸杯用了年半，我今天拿一个十九块的杯子，我就是给自己换了一个身份。</p><p>她说，我知道这个想法很可笑。</p><p>她说，一个人拿一个杯子换一个身份。</p><p>我说，不可笑。</p><p>她说，你今天能不能不讲“不可笑”。</p><p>我说，那讲什么。</p><p>她说，讲一句你也要买一个。</p><p>我说，那我今天去买一个。</p><p>她说，你别今天，你明天。</p><p>我说，为什么明天。</p><p>她说，因为你自己讲过，你这个月只留了吃饭的钱。</p><p>我拿着手机，坐在那儿。</p><p>她讲得对。</p><p>那天我身上只有八十几块，我今天在她面前把这件事报了一句“那我今天去买一个”。</p><p>她在旧号上、在她妈随时能拿起来的手机上，把这句话接住了。</p><p>她没有笑。</p><p>她只是把它挪到明天。</p><p>一百三十七条里，我们一次也没提“以后”。</p>',134)])])}const m=t(o,[["render",r]]);export{l as __pageData,m as default};
